async function readProposal(id) {
  if (!/^[a-zA-Z0-9_-]+$/.test(id)) return null;
  const filename = path.join(process.cwd(), 'component-system', 'proposals', id, 'proposal.json');
  try {
    return JSON.parse(await fs.readFile(filename, 'utf8'));
  } catch {
    return null;
  }
}

