function MediaBlock({ block }) {
  const item = itemOf(block);
  const image = assetOf(block);
  const gallery = galleryOf(item.images);
  return (
    <section
      className={`${styles.block} ${styles.mediaBlock}`}
      data-theme={themeOf(block)}
      data-variant={variantOf(block, 'figure')}
    >
      <div className={styles.blockHeading}>
        {item.eyebrow && <p className={styles.eyebrow}>{item.eyebrow}</p>}
        {item.title && <h2>{item.title}</h2>}
        {item.dek && <p className={styles.dek}>{item.dek}</p>}
      </div>
      {image && (
        <figure className={styles.mediaFigure}>
          <div className={styles.mediaImage}>
            <Image src={image} alt={altOf(block)} fill sizes="100vw" />
          </div>
          {item.caption && <figcaption>{item.caption}</figcaption>}
        </figure>
      )}
      {gallery.length > 0 && variantOf(block, 'figure') === 'gallery' && (
        <div className={styles.galleryGrid}>
          {gallery.map((entry) => (
            <figure key={entry.key}>
              <div className={styles.galleryImage}>
                <Image src={entry.src} alt={entry.alt} fill sizes="(max-width: 700px) 100vw, 50vw" />
              </div>
              {entry.caption && <figcaption>{entry.caption}</figcaption>}
            </figure>
          ))}
        </div>
      )}
    </section>
  );
}

function QuoteBlock({ block }) {
  const item = itemOf(block);
  return (
    <section className={`${styles.block} ${styles.quoteBlock}`} data-theme={themeOf(block)}>
      {item.eyebrow && <p className={styles.eyebrow}>{item.eyebrow}</p>}
      {item.title && <h2>{item.title}</h2>}
      <blockquote>&ldquo;{item.quote || item.dek}&rdquo;</blockquote>
      {item.quote_attribution && <cite>{item.quote_attribution}</cite>}
    </section>
  );
}

function listingSourceKey(item) {
  const type = item.listing_type || 'products';
  return {
    related_objects: 'products',
    related_episodes: 'episodes',
    related_posts: 'posts',
  }[type] || type;
}

function listingItems(item, content) {
  const sourceKey = listingSourceKey(item);
  const source = content?.[sourceKey] || [];
  const filtered = source.filter((entry) => {
    if (item.craft && entry.craft !== item.craft) return false;
    if (item.maker && entry.maker !== item.maker && entry.slug !== item.maker) return false;
    return true;
  });
  return filtered.slice(0, item.items_limit || 6);
}

function listingTitle(entry) {
  return entry.name || entry.title || entry.guest || `Episode ${entry.number}`;
}

function listingMeta(entry) {
  return [entry.craft, entry.place, entry.category, entry.duration].filter(Boolean).join(' / ');
}

function listingHref(item, entry) {
  const sourceKey = listingSourceKey(item);
  if (sourceKey === 'products' && entry.slug) return `/objects/${entry.slug}`;
  if (sourceKey === 'makers' && entry.slug) return `/makers/${entry.slug}`;
  if (sourceKey === 'episodes' && (entry.number || entry.slug)) return `/podcast/${entry.number || entry.slug}`;
  if (sourceKey === 'posts' && entry.slug) return `/journal/${entry.slug}`;
  return '';
}

function ListingBlock({ block, content }) {
  const item = itemOf(block);
  const entries = listingItems(item, content);
  return (
    <section
      className={`${styles.block} ${styles.listingBlock}`}
      data-theme={themeOf(block)}
      data-variant={variantOf(block, 'grid')}
    >
      <div className={styles.blockHeading}>
        {item.eyebrow && <p className={styles.eyebrow}>{item.eyebrow}</p>}
        {item.title && <h2>{item.title}</h2>}
        {item.dek && <p className={styles.dek}>{item.dek}</p>}
      </div>
      <div className={styles.cardGrid}>
        {entries.map((entry, index) => (
          <article className={styles.card} key={entry.slug || entry.number || `${listingTitle(entry)}-${index}`}>
            <a className={styles.cardLink} href={listingHref(item, entry) || undefined}>
              {entry.image && (
                <div className={styles.cardImage}>
                  <Image
                    src={entry.image}
                    alt={listingTitle(entry)}
                    fill
                    sizes="(max-width: 700px) 100vw, 33vw"
                  />
                </div>
              )}
              {listingMeta(entry) && <p className={styles.eyebrow}>{listingMeta(entry)}</p>}
              <h3>{listingTitle(entry)}</h3>
              {(entry.dek || entry.meta) && <p>{entry.dek || entry.meta}</p>}
            </a>
          </article>
        ))}
        {!entries.length && <p className={styles.emptyListing}>No matching items are published yet.</p>}
      </div>
    </section>
  );
}

function CtaBlock({ block }) {
  const item = itemOf(block);
  return (
    <section
      className={`${styles.block} ${styles.ctaBlock}`}
      data-theme={themeOf(block)}
      data-variant={variantOf(block, 'panel')}
    >
      {item.eyebrow && <p className={styles.eyebrow}>{item.eyebrow}</p>}
      <h2>{item.title}</h2>
      {item.dek && <p className={styles.dek}>{item.dek}</p>}
      <Actions item={item} />
    </section>
  );
}

export const BLOCK_COMPONENTS = {
  block_hero: HeroBlock,
  block_text: TextBlock,
  block_media: MediaBlock,
  block_quote: QuoteBlock,
  block_listing: ListingBlock,
  block_cta: CtaBlock,
  block_slideshow: ({ block }) => <SlideshowBlock item={itemOf(block)} />,
  block_podcast_player: ({ block, content }) => <PodcastPlayerBlock item={itemOf(block)} content={content} />,
};

export function DirectusBlock({ block, content, preview = false }) {
  const Component = BLOCK_COMPONENTS[block.collection];
  if (!Component) return null;
  return (
    <div className={styles.componentFrame} data-spacing={spacingOf(block)}>
      <Component block={block} content={content} preview={preview} />
    </div>
  );
}

export function DirectusBlocks({ blocks, content, slot }) {
  if (!blocks?.length) return null;
  return (
    <div className={styles.slot} data-slot={slot}>
      {blocks.map((block) => (
        <DirectusBlock key={`${block.collection}-${block.id}`} block={block} content={content} />
      ))}
    </div>
  );
}

'use client';

import 'media-chrome';
import { ExternalLink } from 'lucide-react';
import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import styles from './directus-page.module.css';

function cleanUrl(value) {
  if (!value || typeof value !== 'string') return '';
  if (value.startsWith('/') || value.startsWith('https://') || value.startsWith('http://')) return value;
  return '';
}

function externalLinks(item) {
  return [
    ['Apple', cleanUrl(item.apple_url)],
    ['Spotify', cleanUrl(item.spotify_url)],
    ['Podbean', cleanUrl(item.podbean_url)],
  ].filter(([, href]) => href);
}

export default function PodcastPlayerBlock({ item = {}, content = {} }) {
  const [mediaReady, setMediaReady] = useState(false);
  const audioUrl = cleanUrl(item.audio_url);
  const links = externalLinks(item);
  const relatedProducts = Array.isArray(item.related_products) ? item.related_products : [];
  const products = (content?.products || [])
    .filter((product) => relatedProducts.includes(product.slug))
    .slice(0, 6);
  const title = item.episode_title || item.title || 'Podcast episode';
  const metadata = [
    item.guest,
    item.duration,
    item.published_date,
  ].filter(Boolean).join(' / ');

  useEffect(() => {
    setMediaReady(true);
  }, []);

  return (
    <section
      aria-label={`${title} podcast player`}
      className={`${styles.block} ${styles.podcastPlayerBlock}`}
      data-theme={item.theme || 'paper'}
      data-variant={item.variant || 'feature'}
    >
      <div className={styles.podcastPlayerHeader}>
        <div>
          {item.eyebrow && <p className={styles.eyebrow}>{item.eyebrow}</p>}
          <h2>{title}</h2>
          {metadata && <p className={styles.podcastMeta}>{metadata}</p>}
        </div>
        {item.dek && <p className={styles.dek}>{item.dek}</p>}
      </div>

      <div className={styles.podcastPlayerShell}>
        {audioUrl && mediaReady ? (
          <media-controller audio className={styles.mediaController}>
            <audio
              preload="metadata"
              slot="media"
              src={audioUrl}
            />
            <media-control-bar className={styles.mediaControlBar}>
              <media-play-button aria-label="Play or pause episode" />
              <media-time-range aria-label="Seek episode" />
              <media-time-display show-duration />
              <media-mute-button aria-label="Mute episode" />
            </media-control-bar>
          </media-controller>
        ) : audioUrl ? (
          <div aria-hidden="true" className={styles.mediaControllerPlaceholder} />
        ) : (
          <p className={styles.emptyListing}>No audio URL has been added for this episode yet.</p>
        )}

        <div className={styles.podcastPlayerActions}>
          {item.transcript && (
            <Button asChild className="rounded-none" size="sm" variant="outline">
              <a href={`#transcript-${item.episode || title}`}>Transcript</a>
            </Button>
          )}
          {links.map(([label, href]) => (
            <Button asChild className="rounded-none" key={label} size="sm" variant="outline">
              <a href={href} rel="noreferrer" target="_blank">
                {label}
                <ExternalLink aria-hidden="true" size={14} />
              </a>
            </Button>
          ))}
        </div>
      </div>

      {item.transcript && (
        <details className={styles.podcastTranscript} id={`transcript-${item.episode || title}`}>
          <summary>Transcript</summary>
          <p>{item.transcript}</p>
        </details>
      )}

      {products.length > 0 && (
        <div className={styles.podcastRelated}>
          <p className={styles.eyebrow}>Objects from this conversation</p>
          <div>
            {products.map((product) => (
              <a href={`/objects/${product.slug}`} key={product.slug}>
                <span>{product.name}</span>
                <small>{[product.craft, product.price].filter(Boolean).join(' / ')}</small>
              </a>
            ))}
          </div>
        </div>
      )}
    </section>
  );
}

'use client';

import Image from 'next/image';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { Button } from '@/components/ui/button';
import {
  Carousel,
  CarouselContent,
  CarouselItem,
} from '@/components/ui/carousel';
import {
  normalizeSlideshowSlides,
  shouldRunSlideshowAutoplay,
  slideshowInterval,
  wrappedSlideIndex,
} from '@/lib/slideshow.mjs';
import styles from './directus-page.module.css';

export default function SlideshowBlock({ item }) {
  const slides = useMemo(() => normalizeSlideshowSlides(item.slides), [item.slides]);
  const [api, setApi] = useState(null);
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(!item.autoplay);
  const [reducedMotion, setReducedMotion] = useState(true);
  const interval = slideshowInterval(item.interval);

  const goTo = (next) => {
    if (!api || !slides.length) return;
    api.scrollTo(wrappedSlideIndex(next, slides.length));
  };

  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const updatePreference = () => setReducedMotion(query.matches);
    updatePreference();
    query.addEventListener?.('change', updatePreference);
    return () => query.removeEventListener?.('change', updatePreference);
  }, []);

  useEffect(() => {
    if (!api) return undefined;
    const onSelect = () => setIndex(api.selectedScrollSnap());
    onSelect();
    api.on('select', onSelect);
    api.on('reInit', onSelect);
    return () => {
      api.off('select', onSelect);
      api.off('reInit', onSelect);
    };
  }, [api]);

  useEffect(() => {
    if (!api || !shouldRunSlideshowAutoplay({
      autoplay: item.autoplay,
      paused,
      reducedMotion,
      slideCount: slides.length,
    })) return undefined;
    const timer = window.setInterval(() => {
      if (api.canScrollNext()) api.scrollNext();
      else api.scrollTo(0);
    }, interval);
    return () => window.clearInterval(timer);
  }, [api, interval, item.autoplay, paused, reducedMotion, slides.length]);

  if (!slides.length) return null;
  const current = slides[index] || slides[0];
  const showCaptions = item.show_captions !== false;
  const hasCaptions = slides.some((slide) => slide.caption || slide.credit);
  const captionText = (slide) => (
    <>
      {slide.caption}
      {slide.caption && slide.credit && ' / '}
      {slide.credit}
    </>
  );

  return (
    <section
      aria-label={item.title || 'Image slideshow'}
      className={`${styles.block} ${styles.slideshowBlock}`}
      data-theme={item.theme || 'paper'}
      data-variant={item.variant || 'editorial'}
    >
      <div className={styles.slideshowHeading}>
        <div>
          {item.eyebrow && <p className={styles.eyebrow}>{item.eyebrow}</p>}
          {item.title && <h2>{item.title}</h2>}
        </div>
        {item.dek && <p className={styles.dek}>{item.dek}</p>}
      </div>

      <Carousel
        aria-label={item.title || 'Image slideshow'}
        className={styles.slideshowStage}
        opts={{ align: 'start', loop: false }}
        setApi={setApi}
      >
        <CarouselContent className={styles.slideshowTrack}>
          {slides.map((slide, slideIndex) => (
            <CarouselItem key={slide.key}>
              <div className={styles.slideshowImage}>
                <Image
                  alt={slide.alt}
                  fill
                  loading={slideIndex === 0 ? 'eager' : 'lazy'}
                  sizes="(max-width: 900px) 100vw, 88vw"
                  src={slide.src}
                />
              </div>
            </CarouselItem>
          ))}
        </CarouselContent>

        <div className={styles.slideshowControls}>
          <div>
            <Button
              aria-label="Previous slide"
              className="rounded-none"
              onClick={() => goTo(index - 1)}
              size="icon-lg"
              type="button"
              variant="outline"
            >
              <ChevronLeft aria-hidden="true" />
            </Button>
            <Button
              aria-label="Next slide"
              className="rounded-none"
              onClick={() => goTo(index + 1)}
              size="icon-lg"
              type="button"
              variant="outline"
            >
              <ChevronRight aria-hidden="true" />
            </Button>
          </div>
          {item.show_counter !== false && (
            <p aria-live={item.autoplay && !paused ? 'off' : 'polite'} className={styles.slideshowCounter}>
              {String(index + 1).padStart(2, '0')} / {String(slides.length).padStart(2, '0')}
            </p>
          )}
          {item.autoplay && (
            <Button
              aria-label={paused ? 'Play slideshow' : 'Pause slideshow'}
              className={`${styles.slideshowPlayback} rounded-none`}
              onClick={() => setPaused((value) => !value)}
              size="sm"
              type="button"
              variant="outline"
            >
              {paused ? 'Play' : 'Pause'}
            </Button>
          )}
        </div>

        {showCaptions && hasCaptions && (
          <div aria-live="polite" className={styles.slideshowCaptionFrame}>
            {slides.map((slide) => (
              <p
                aria-hidden="true"
                className={`${styles.slideshowCaption} ${styles.slideshowCaptionSizer}`}
                key={`${slide.key}-caption-size`}
              >
                {captionText(slide)}
              </p>
            ))}
            <p className={styles.slideshowCaption}>
              {captionText(current)}
            </p>
          </div>
        )}
      </Carousel>

      {(item.variant === 'thumbnail-rail') && (
        <div aria-label="Choose slide" className={styles.slideshowThumbnails}>
          {slides.map((slide, slideIndex) => (
            <Button
              aria-current={slideIndex === index ? 'true' : undefined}
              aria-label={`Show slide ${slideIndex + 1}`}
              className="rounded-none p-0"
              key={slide.key}
              onClick={() => goTo(slideIndex)}
              type="button"
              variant="ghost"
            >
              <Image alt="" fill sizes="120px" src={slide.src} />
            </Button>
          ))}
        </div>
      )}
    </section>
  );
}

